     1	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
     2	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
     3	// Super on Linux. See orca.nix.
     4	//
     5	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
     6	//
     7	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
     8	// facade its comment promises) for the definitions, normalisation and the
     9	// conflict check, so a version bump regenerates the table instead of
    10	// silently drifting from it.
    11	const fs = require('fs');
    12	const path = require('path');
    13	
    14	const [shared, chordsFile] = process.argv.slice(2);
    15	const kb = require(path.resolve(shared, 'keybindings.js'));
    16	
    17	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
    18	// "Cmd+Shift+W". Mouse, switch and media-key binds cannot be an Orca chord;
    19	// anything else that does not translate is an error, not a free chord.
    20	const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
    21	const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
    22	const taken = new Set();
    23	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
    24	  const parts = chord.split('+').map((s) => s.trim());
    25	  const key = parts.pop();
    26	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
    27	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
    28	  const n = mods.every(Boolean) && kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
    29	  if (!n || !n.ok) throw new Error(`cannot translate Hyprland bind "${chord}" to an Orca chord`);
    30	  taken.add(n.value);
    31	}
    32	// A digit-index action's one binding stands for its whole 1-9 family.
    33	const isTaken = (id, binding) =>
    34	  kb.isDigitIndexActionId(id)
    35	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
    36	    : taken.has(binding);
    37	
    38	const overrides = {};
    39	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
    40	const fellBack = new Set();
    41	for (const def of kb.KEYBINDING_DEFINITIONS) {
    42	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
    43	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
    44	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
    45	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
    46	    return n.value;
    47	  });
    48	  const free = mac.filter((b) => !isTaken(def.id, b));
    49	  if (free.length < mac.length) {
    50	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
    51	  }
    52	  // Every chord taken: leave the action on its Linux default rather than
    53	  // unbinding it. No macOS binding at all is different -- unbound there, so
    54	  // unbound here ([]). Same as the Linux default: nothing to say.
    55	  if (mac.length > 0 && free.length === 0) {
    56	    fellBack.add(def.id);
    57	    continue;
    58	  }
    59	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
    60	  overrides[def.id] = free;
    61	}
    62	
    63	// A fallback can land on a generated chord the Mac table never had to keep
    64	// apart from it. Orca dispatches some actions across scopes, ahead of the
    65	// conflict check's scope groups -- the workspace digits before the tab
    66	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
    67	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
    68	// Such an action goes back to its own Linux default too, until none is left.
    69	const identities = (id, bindings) =>
    70	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
    71	for (;;) {
    72	  const held = new Set(
    73	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
    74	  );
    75	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
    76	  if (shadowed.length === 0) break;
    77	  for (const id of shadowed) {
    78	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
    79	    delete overrides[id];
    80	    fellBack.add(id);
    81	  }
    82	}
    83	
    84	// Orca drops every action in a conflicting set at load, with only a line in
    85	// its diagnostics; fail the build instead.
    86	const conflicts = kb.findKeybindingConflicts('linux', overrides);
    87	if (conflicts.length > 0) {
    88	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
    89	}
    90	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
    91	// Merges the generated overrides (orca-mac-keybindings.js) into
    92	// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
    93	//
    94	//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
    95	//
    96	// The file is Orca's read-write state, so this owns only what it wrote: a
    97	// sidecar, keybindings.nix-owned.json, records the values of the last write.
    98	//   - a key written last time and no longer generated is removed;
    99	//   - a key whose value the UI has changed since is left as the UI's;
   100	//   - everything else in the file is untouched.
   101	// Then the merged file gets Orca's own conflict check. Orca drops every
   102	// action in a conflicting set at load, so a generated key that clashes with
   103	// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
   104	// the generated action's Linux default.
   105	const fs = require('fs');
   106	const os = require('os');
   107	const path = require('path');
   108	
   109	// Activation runs under set -e, so a throw here would abandon the rest of
   110	// the switch over a keybinding file. Any failure is one line and exit 0;
   111	// the file is then exactly as it was, since writes only ever rename over it.
   112	process.on('uncaughtException', (e) => {
   113	  console.error(`orca: keybinding merge skipped: ${e.message}`);
   114	  process.exit(0);
   115	});
   116	
   117	const [shared, ownedFile] = process.argv.slice(2);
   118	const kb = require(path.resolve(shared, 'keybindings.js'));
   119	const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
   120	
   121	const dir = path.join(os.homedir(), '.orca');
   122	const dest = path.join(dir, 'keybindings.json');
   123	const sidecar = path.join(dir, 'keybindings.nix-owned.json');
   124	const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
   125	const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
   126	
   127	// Orca's own writer (G$): whole file to a temp name, rename over, and the
   128	// temp removed if either step fails.
   129	function writeJson(file, value) {
   130	  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
   131	  try {
   132	    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
   133	    fs.renameSync(tmp, file);
   134	  } catch (e) {
   135	    fs.rmSync(tmp, { force: true });
   136	    throw e;
   137	  }
   138	}
   139	
   140	fs.mkdirSync(dir, { recursive: true });
   141	let doc;
   142	if (!fs.existsSync(dest)) {
   143	  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
   144	} else {
   145	  let why = null;
   146	  try {
   147	    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
   148	    if (!isObject(doc)) why = 'not a JSON object';
   149	  } catch (e) {
   150	    why = e.message;
   151	  }
   152	  if (why !== null) {
   153	    // Orca's loader rejects it too and says so; overwriting would lose
   154	    // whatever the user was halfway through editing.
   155	    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
   156	    process.exit(0);
   157	  }
   158	}
   159	
   160	let prev = {};
   161	try {
   162	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
   163	  if (!isObject(s?.linux)) throw new Error('no .linux object');
   164	  prev = s.linux;
   165	} catch (e) {
   166	  // No sidecar is a first run. A bad one stops the merge: it decides what
   167	  // may be overwritten, and reading it as empty overwrites every key the UI
   168	  // has changed.
   169	  if (e.code !== 'ENOENT') {
   170	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
   171	    process.exit(0);
   172	  }
   173	}
   174	
   175	const platforms = isObject(doc.platforms) ? doc.platforms : {};
   176	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
   177	// Changed since the last write: the UI's now. Absent (reset in the UI)
   178	// is not a change -- the reset target is this table, so it comes back.
   179	const theirs = new Set(Object.keys(prev).filter((id) => id in linux && !same(linux[id], prev[id])));
   180	for (const id of Object.keys(prev)) {
   181	  if (!theirs.has(id)) delete linux[id];
   182	}
   183	// What the UI had on each key about to be overwritten, for a withdrawal
   184	// below to put back. Stale keys are gone by now, so anything left is the UI's.
   185	const before = {};
   186	const written = {};
   187	for (const [id, bindings] of Object.entries(owned)) {
   188	  if (theirs.has(id)) continue;
   189	  if (id in linux) before[id] = linux[id];
   190	  linux[id] = bindings;
   191	  written[id] = bindings;
   192	}
   193	
   194	// What Orca's loader feeds its conflict pass: common, then the platform
   195	// section over it, with its string shorthand and null/false expanded.
   196	// Common is the root's action keys in the legacy shape with no .keybindings.
   197	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
   198	// Orca's loader (jHn): null/false unbind; a string is a comma list; an array
   199	// of strings may hold comma lists too; one bad chord rejects the whole value,
   200	// leaving the action on its default (undefined here).
   201	const expand = (id, v) => {
   202	  if (v === null || v === false) return [];
   203	  const n =
   204	    typeof v === 'string' ? kb.normalizeKeybindingListForAction(id, v)
   205	      : Array.isArray(v) && v.every((b) => typeof b === 'string') ? kb.normalizeKeybindingArrayForAction(id, v)
   206	        : { ok: false };
   207	  return Array.isArray(n) ? n : n.ok ? [n.value] : undefined;
   208	};
   209	const effective = {};
   210	for (const [id, v] of Object.entries({ ...common, ...linux })) {
   211	  if (kb.isKeybindingActionId(id) && expand(id, v) !== undefined) effective[id] = expand(id, v);
   212	}
   213	for (;;) {
   214	  const withdrawn = kb
   215	    .findKeybindingConflicts('linux', effective)
   216	    .flatMap((c) => c.actionIds)
   217	    .filter((id) => id in written);
   218	  // Only generated keys are ever withdrawn. A conflict with none left in it
   219	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
   220	  // withdrawal brought back -- is Orca's to report.
   221	  if (withdrawn.length === 0) break;
   222	  for (const id of new Set(withdrawn)) {
   223	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
   224	    delete written[id];
   225	    if (id in before) {
   226	      linux[id] = before[id];
   227	    } else {
   228	      delete linux[id];
   229	    }
   230	    const fallback = id in linux ? linux[id] : common[id];
   231	    if (kb.isKeybindingActionId(id) && expand(id, fallback) !== undefined) effective[id] = expand(id, fallback);
   232	    else delete effective[id];
   233	  }
   234	}
   235	
   236	doc.version = 1;
   237	doc.platforms = {
   238	  ...platforms,
   239	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   240	  linux,
   241	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   242	};
   243	writeJson(dest, doc);
   244	// Every key this table claims, written or withdrawn, at its generated value;
   245	// the UI's keep the value last written. Either way a later UI value reads as
   246	// changed, the UI's, rather than as never owned and free to overwrite.
   247	writeJson(sidecar, {
   248	  linux: { ...Object.fromEntries([...theirs].map((id) => [id, prev[id]])), ...owned, ...written },
   249	});
diff --git a/orca.nix b/orca.nix
index 72e5e26b..50407e33 100644
--- a/orca.nix
+++ b/orca.nix
@@ -89,6 +89,59 @@ let
   # Extracted once, shared by the wrapper's extraInstallCommands below;
   # let bindings are recursive, so position in the block does not matter.
   appimageContents = pkgs.appimageTools.extract { inherit pname version src; };
+
+  # Mac-style shortcuts, the same Super-for-Cmd scheme as gtk's mac-bindings
+  # and ghostty's super+c/v in home.nix: Orca's own macOS defaults, with Cmd
+  # spelled out, which Orca binds to Super (event.metaKey) on Linux. Ctrl+C is
+  # SIGINT again, not copy; Ctrl+Tab and Ctrl+PageUp/Down cycle tabs, as on a
+  # Mac.
+  #
+  # Generated from the app's own keybinding definitions at build time
+  # (nix/orca-mac-keybindings.js), so a version bump picks up new actions.
+  # Chords Hyprland binds are skipped and those actions keep their Linux Ctrl
+  # default -- the compositor would eat them, leaving a dead key. On shiori
+  # that is 19 actions, Super+F (find) and Super+P (go to file) among them,
+  # plus Super+B/N/E, the digits, and their Shift forms; so Ctrl+F/P/B/N/E stay
+  # Orca's. And an action whose Mac chord such a fallback would shadow falls
+  # back too: tab.selectByIndex keeps Alt+1..9, since Ctrl+1..9 stays the
+  # workspaces'. The build log lists every one.
+  #
+  # A running Orca reads the file once; after a switch, restart it (or run its
+  # keybindings reload) for the new table to apply.
+  hyprlandChords = let s = config.wayland.windowManager.hyprland.settings; in
+    lib.concatMap
+      (k: map (b: if builtins.isAttrs b && b ? _args then builtins.head b._args else b) s.${k})
+      # bind, bindl, binde, ...: the lists. `binds` is a config section, a set.
+      (builtins.filter (k: lib.hasPrefix "bind" k && builtins.isList s.${k}) (builtins.attrNames s));
+  macKeybindings = pkgs.runCommand "orca-mac-keybindings" {
+    nativeBuildInputs = [ pkgs.nodejs pkgs.asar pkgs.makeWrapper ];
+  } ''
+    asar extract ${appimageContents}/resources/app.asar app
+    mkdir -p $out/share $out/bin
+    node ${./nix/orca-mac-keybindings.js} app/out/shared \
+      ${pkgs.writeText "hyprland-chords.json" (builtins.toJSON hyprlandChords)} \
+      > $out/share/orca-mac-keybindings.json
+    # The merge runs Orca's conflict check on the merged file at activation,
+    # so the keybinding module (and its one sibling import) ships alongside.
+    mkdir -p $out/lib/shared
+    cp -r app/out/shared/keybindings.js app/out/shared/keybindings \
+      app/out/shared/tui-agent-display-names.js $out/lib/shared/
+    makeWrapper ${pkgs.nodejs}/bin/node $out/bin/orca-mac-keybindings \
+      --add-flags "${./nix/orca-mac-keybindings-merge.js} $out/lib/shared $out/share/orca-mac-keybindings.json"
+    # One real merge, so an Orca bump that moves an import or an export the
+    # merge uses fails here, not as a warning at every activation.
+    HOME=$TMPDIR/home $out/bin/orca-mac-keybindings 2> merge.err
+    if [ -s merge.err ] || [ ! -s $TMPDIR/home/.orca/keybindings.json ]; then
+      cat merge.err >&2; exit 1
+    fi
+  '';
+  # ~/.orca/keybindings.json is Orca's read-write state: its settings UI saves
+  # into the same platforms.linux section, by atomic rename, so a home.file
+  # symlink would be replaced on the first edit. So the generated keys are
+  # merged into whatever Orca last wrote, owning only what the last merge
+  # wrote (a sidecar records it), and a UI edit outranks them -- the rules
+  # are at the top of nix/orca-mac-keybindings-merge.js.
+  # tests/orca-mac-keybindings.sh.
 in
 {
   home.packages =
@@ -98,4 +151,9 @@ in
     # same reason parsec gets it.
       (config.lib.nixGL.wrap orca)
     ];
+
+  home.activation.orcaMacKeybindings = lib.mkIf (!isDarwin && isDesktop)
+    (lib.hm.dag.entryAfter [ "writeBoundary" ] ''
+      $DRY_RUN_CMD ${macKeybindings}/bin/orca-mac-keybindings
+    '');
 }

