// usage: node shadow.js <shared> <policy.js> <overrides.json>
const fs = require('fs'), path = require('path');
const [shared, policyFile, ovFile] = process.argv.slice(2);
const kb = require(path.resolve(shared, 'keybindings.js'));
const ov = JSON.parse(fs.readFileSync(ovFile, 'utf8'));
const src = fs.readFileSync(policyFile, 'utf8');
// window dispatcher order, extracted from resolveWindowShortcutAction body
const body = src.slice(src.indexOf('function resolveWindowShortcutAction'), src.indexOf('function getWindowShortcutActionId'));
const order = [...body.matchAll(/(?:actionMatches|matchKeybindingDigitIndex)\)?\('([^']+)'/g)].map((m) => m[1]);
console.error('window order:', order.join(' '));
const ids = (id) => kb.getEffectiveKeybindingsForAction(id, 'linux', ov).flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
const winOwner = new Map();
for (const id of order) for (const i of ids(id)) if (!winOwner.has(i)) winOwner.set(i, id);
let bad = 0;
for (const def of kb.KEYBINDING_DEFINITIONS) {
  for (const b of kb.getEffectiveKeybindingsForAction(def.id, 'linux', ov)) {
    for (const i of kb.keybindingConflictIdentities(def.id, b, 'linux')) {
      const w = winOwner.get(i);
      if (w && w !== def.id) { bad++; console.log(`${def.id} ${b} (${i}) -> window ${w}${def.id in ov ? ' [generated]' : ' [default]'}`); }
    }
  }
}
console.log(`shadowed: ${bad}`);
EOF
